  'booth': <OpenCetRichExampleRow>[
    OpenCetRichExampleRow(
      exampleId: 'tatoeba:540700:838546',
      sourceId: 'tatoeba-cc-by-2.0-fr',
      englishText: 'Where\'s the nearest telephone booth?',
      chineseText: '最近的電話亭在哪裡？',
